public void visitElement(XmlContext context, Element element) {
    if (!isTextField(element)) return;
    String inputType = element.getAttributeNS(ANDROID_URI, ATTR_INPUT_TYPE);
    String id = element.getAttributeNS(ANDROID_URI, ATTR_ID);
    if (inputType == null || inputType.isEmpty()) {
        reportMissing(context, element);
        return;
    }
    if (inputType.equals("text")) {
        return;
    }
    int type = parseInputType(inputType);
    String idName = getIdName(id);
    if (idName != null) {
        if (idName.contains("email")) {
            if (!isEmailType(type)) {
                context.report(ISSUE, element, context.getLocation(element),
                    "The id of this field suggests it should be an email address; add `textEmailAddress` to the `inputType`");
            }
        } else if (idName.contains("phone")) {
            if (!isPhoneType(type)) {
                context.report(...);
            }
        }
    }
}
```

