    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(
                SdkConstants.EDIT_TEXT,
                SdkConstants.AUTO_COMPLETE_TEXT_VIEW,
                SdkConstants.MULTI_AUTO_COMPLETE_TEXT_VIEW,
                EXTRACT_EDIT_TEXT);
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        if (!isTextField(element)) {
            return;
        }

        String inputType =
                element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_INPUT_TYPE).trim();
        String id = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_ID);

        if (inputType.isEmpty()) {
            context.report(
                    ISSUE,
                    element,
                    context.getNameLocation(element),
                    "This text field does not specify an `inputType`");
            return;
        }

        if ("text".equals(inputType)) {
            return;
        }

        String idName = getIdName(id);
        if (idName == null) {
            return;
        }

        int type = parseInputType(inputType);
        if (type == -1) {
            return;
        }

        Attr inputTypeNode =
                element.getAttributeNodeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_INPUT_TYPE);

        if (containsWord(idName, "email")) {
            if (!isEmailInputType(type)) {
                context.report(
                        ISSUE,
                        element,
                        context.getLocation(inputTypeNode),
                        "The id of this field suggests it should accept an email address; "
                                + "add `textEmailAddress` (or `textWebEmailAddress`) to its `inputType`");
            }
        } else if (containsWord(idName, "phone")) {
            if (!isPhoneInputType(type)) {
                context.report(
                        ISSUE,
                        element,
                        context.getLocation(inputTypeNode),
                        "The id of this field suggests it should accept a phone number; "
                                + "set its `inputType` to `phone`");
            }
        }
    }

    private static boolean isTextField(Element element) {
        String tag = element.getTagName();
        return tag.equals(SdkConstants.EDIT_TEXT)
                || tag.equals(SdkConstants.AUTO_COMPLETE_TEXT_VIEW)
                || tag.equals(SdkConstants.MULTI_AUTO_COMPLETE_TEXT_VIEW)
                || tag.equals(EXTRACT_EDIT_TEXT)
                || tag.endsWith("." + SdkConstants.EDIT_TEXT)
                || tag.endsWith("." + SdkConstants.AUTO_COMPLETE_TEXT_VIEW)
                || tag.endsWith("." + SdkConstants.MULTI_AUTO_COMPLETE_TEXT_VIEW)
                || tag.endsWith("." + EXTRACT_EDIT_TEXT);
    }

    private static String getIdName(String id) {
        if (id == null || id.isEmpty()) {
            return null;
        }
        int index = id.lastIndexOf('/');
        String name = index >= 0 ? id.substring(index + 1) : id;
        return name.toLowerCase(Locale.US);
    }

    private static int parseInputType(String inputType) {
        int result = 0;
        for (String token : inputType.split("\\|")) {
            token = token.trim();
            if (token.isEmpty()) {
                continue;
            }
            Integer value = INPUT_TYPE_MAP.get(token);
            if (value != null) {
                result |= value;
            } else {
                try {
                    result |= Integer.decode(token);
                } catch (NumberFormatException e) {
                    return -1;
                }
            }
        }
        return result;
    }

    private static boolean isPhoneInputType(int type) {
        return (type & TYPE_MASK_CLASS) == TYPE_CLASS_PHONE;
    }

    private static boolean isEmailInputType(int type) {
        int masked = type & (TYPE_MASK_CLASS | TYPE_MASK_VARIATION);
        return masked == TYPE_TEXT_VARIATION_EMAIL_ADDRESS
                || masked == TYPE_TEXT_VARIATION_WEB_EMAIL_ADDRESS
                || masked == TYPE_TEXT_VARIATION_EMAIL_SUBJECT;
    }

    static boolean containsWord(String name, String word) {
        return containsWord(name, word, false, false);
    }

    static boolean containsWord(String name, String word, boolean allowPrefix, boolean allowSuffix) {
        if (name == null || word == null) {
            return false;
        }
        if (name.equalsIgnoreCase(word)) {
            return true;
        }
        int wordLength = word.length();
        if (name.length() < wordLength) {
            return false;
        }
        String lowerName = name.toLowerCase(Locale.US);
        String lowerWord = word.toLowerCase(Locale.US);
        int index = lowerName.indexOf(lowerWord);
        while (index != -1) {
            if (index > 0) {
                char prev = name.charAt(index - 1);
                char first = name.charAt(index);
                boolean boundary = !Character.isJavaIdentifierPart(prev)
                        || (Character.isLowerCase(prev) && Character.isUpperCase(first));
                if (!boundary && !allowPrefix) {
                    index = lowerName.indexOf(lowerWord, index + 1);
                    continue;
                }
            }
            if (index + wordLength < name.length()) {
                char last = name.charAt(index + wordLength - 1);
                char next = name.charAt(index + wordLength);
                boolean boundary = !Character.isJavaIdentifierPart(next)
                        || (Character.isLowerCase(last) && Character.isUpperCase(next));
                if (!boundary && !allowSuffix) {
                    index = lowerName.indexOf(lowerWord, index + 1);
                    continue;
                }
            }
            return true;
        }
        return false;
    }
}
